1	export type Cell = [x: number, y: number];
2	
3	const NEIGHBOR_OFFSETS: ReadonlyArray<Cell> = [
4	  [-1, -1], [-1, 0], [-1, 1],
5	  [ 0, -1],          [ 0, 1],
6	  [ 1, -1], [ 1, 0], [ 1, 1],
7	];
8	
9	const toKey = ([x, y]: Cell): string => `${x},${y}`;
10	
11	const survivesConwayRule = (neighborCount: number, isCurrentlyAlive: boolean): boolean =>
12	  neighborCount === 3 || (neighborCount === 2 && isCurrentlyAlive);
13	
14	export function nextGeneration(livingCells: Cell[]): Cell[] {
15	  const aliveKeys = new Set(livingCells.map(toKey));
16	  const neighborCounts = countNeighbors(livingCells);
17	
18	  return [...neighborCounts.values()]
19	    .filter(({ cell, count }) => survivesConwayRule(count, aliveKeys.has(toKey(cell))))
20	    .map(({ cell }) => cell);
21	}
22	
23	type NeighborEntry = { cell: Cell; count: number };
24	
25	function countNeighbors(livingCells: Cell[]): Map<string, NeighborEntry> {
26	  const counts = new Map<string, NeighborEntry>();
27	  for (const [x, y] of livingCells) {
28	    for (const [dx, dy] of NEIGHBOR_OFFSETS) {
29	      const cell: Cell = [x + dx, y + dy];
30	      const key = toKey(cell);
31	      const previous = counts.get(key)?.count ?? 0;
32	      counts.set(key, { cell, count: previous + 1 });
33	    }
34	  }
35	  return counts;
36	}
37

1	import { describe, it, expect } from "vitest";
2	import { nextGeneration } from "./game-of-life.js";
3	
4	describe("Game of Life - nextGeneration", () => {
5	  it("empty grid stays empty — [] → []", () => {
6	    expect(nextGeneration([])).toEqual([]);
7	  });
8	  it("single live cell dies from underpopulation — [(0,0)] → []", () => {
9	    expect(nextGeneration([[0, 0]])).toEqual([]);
10	  });
11	  it("Rule 1 (Underpopulation): two adjacent cells die — [(0,1), (1,1)] → []", () => {
12	    expect(nextGeneration([[0, 1], [1, 1]])).toEqual([]);
13	  });
14	  it("Rule 4 (Reproduction): dead cell with exactly 3 neighbors becomes alive — L-shape [(0,2),(1,2),(0,1)] → [(0,1),(1,1),(0,2),(1,2)]", () => {
15	    const result = nextGeneration([[0, 2], [1, 2], [0, 1]]);
16	    expect(new Set(result.map((c) => c.join(",")))).toEqual(
17	      new Set([[0, 1], [1, 1], [0, 2], [1, 2]].map((c) => c.join(","))),
18	    );
19	  });
20	  it("Rule 2 (Survival): live cell with 3 neighbors survives — diagonal cluster around (1,1)", () => {
21	    // (1,1) has 3 live neighbors: (0,0), (2,0), (0,2) → survives
22	    const result = nextGeneration([[1, 1], [0, 0], [2, 0], [0, 2]]);
23	    const resultSet = new Set(result.map((c) => c.join(",")));
24	    expect(resultSet.has("1,1")).toBe(true);
25	  });
26	  it("Rule 3 (Overpopulation): live cell with more than 3 neighbors dies — center of ###/.#./### dies", () => {
27	    // Center (1,1) has 6 live neighbors → dies
28	    const result = nextGeneration([
29	      [0, 0], [1, 0], [2, 0],
30	      [1, 1],
31	      [0, 2], [1, 2], [2, 2],
32	    ]);
33	    const resultSet = new Set(result.map((c) => c.join(",")));
34	    expect(resultSet.has("1,1")).toBe(false);
35	  });
36	  it("Block still life stays the same — [(0,0),(1,0),(0,1),(1,1)] unchanged", () => {
37	    const block: Array<[number, number]> = [[0, 0], [1, 0], [0, 1], [1, 1]];
38	    const result = nextGeneration(block);
39	    expect(new Set(result.map((c) => c.join(",")))).toEqual(
40	      new Set(block.map((c) => c.join(","))),
41	    );
42	  });
43	  it("Blinker oscillates — vertical [(0,0),(0,1),(0,2)] → horizontal [(-1,1),(0,1),(1,1)]", () => {
44	    const result = nextGeneration([[0, 0], [0, 1], [0, 2]]);
45	    expect(new Set(result.map((c) => c.join(",")))).toEqual(
46	      new Set([[-1, 1], [0, 1], [1, 1]].map((c) => c.join(","))),
47	    );
48	  });
49	  it("Handles negative coordinates — blinker at negative coords oscillates correctly", () => {
50	    // Vertical blinker at (-5,-5),(-5,-4),(-5,-3) → horizontal (-6,-4),(-5,-4),(-4,-4)
51	    const result = nextGeneration([[-5, -5], [-5, -4], [-5, -3]]);
52	    expect(new Set(result.map((c) => c.join(",")))).toEqual(
53	      new Set([[-6, -4], [-5, -4], [-4, -4]].map((c) => c.join(","))),
54	    );
55	  });
56	});
